            local rel = Vector3.new(p.X - cur.Position.X, 0, p.Z - cur.Position.Z)
            local lat = seg.Magnitude > 1 and (rel - seg.Unit * rel:Dot(seg.Unit)).Magnitude or rel.Magnitude
            if lat > 20 then off += 1 else off = 0 end
            hist[#hist + 1] = p
            if #hist > 5 then table.remove(hist, 1) end
            local noProgress = #hist >= 5 and (hist[#hist] - hist[1]).Magnitude < 40
            if stuck >= 3 or off >= 2 or noProgress then recover() end
        end
    end
    E.driving = false
    c:Disconnect()
    E.throttle(0)
    pcall(function() C.SetThrottle:Fire(0) end)
    if E.car() then E.zero(E.car()) end
    return G.miles() - m0
end
