J.claimAt = {}
function J.claimAll(force)
    local function due(k, sec) if force or os.clock() - (J.claimAt[k] or -1e9) > sec then J.claimAt[k] = os.clock() return true end end
    local got = {}
    if due("gift", 3600) then local ok = G.ask("Databases.Store.Featured.ClaimFreeGift") if ok == true then got[#got + 1] = "free gift" end end
    if due("spin", 600) then
        local st = G.ask("Databases.Spinners.GetSpinnerState", "Standard")
        if type(st) == "table" and st.FreeSpinAvailable == true then local ok = G.ask("Databases.Spinners.Spin", "Standard", "Free") if ok == true then got[#got + 1] = "free spin" end end
    end
    if due("daily", 600) then local t = G.ask("Databases.DailyRewards.GetTimeUntilNextReward") if tonumber(t) and tonumber(t) <= 0 then G.fire("Databases.DailyRewards.ClaimNextReward") got[#got + 1] = "daily" end end
    if due("offline", 3600) then local ok = G.ask("Remotes.Services.OfflineIncomeServiceRemotes.Claim") if ok == true then got[#got + 1] = "offline cash" end end
    if due("hday", 600) then G.fire("Databases.HalloweenEvent.ClaimDailyReward") end
    if due("giveaway", 3600) then G.ask("Remotes.Services.FreeCarGiveawayServiceRemotes.ClaimGiveawayCar") end
    if #got > 0 then say(__T["Claimed "] .. table.concat(got, ", ")) end
end
task.spawn(function()
    task.wait(5)
    while RUNNING do
        if on("cl_auto") then pcall(J.claimAll) end
        task.wait(20)
    end
end)
