function X.marker(key, pos, text, color)
    local e = X.esp[key]
    if not e then
        local p = Instance.new("Part")
        p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.Transparency, p.Size = true, false, false, false, 1, Vector3.new(1, 1, 1)
        p.Parent = X.folder
        local b = Instance.new("BillboardGui")
        b.Size, b.AlwaysOnTop, b.StudsOffset, b.Adornee = UDim2.fromOffset(150, 22), true, Vector3.new(0, 3, 0), p
        local l = Instance.new("TextLabel")
        l.Size, l.BackgroundTransparency, l.TextStrokeTransparency, l.Font, l.TextSize = UDim2.fromScale(1, 1), 1, 0.3, Enum.Font.GothamBold, 13
        l.Parent = b b.Parent = p
        e = { p = p, l = l } X.esp[key] = e
    end
    e.p.Position = pos e.l.Text = text e.l.TextColor3 = color e.seen = true
end
