track(RunService.Heartbeat:Connect(function(dt)
    X.dt = dt
    if not RUNNING then return end
    if on("wd_bright") then
        if not X.bright then X.bright = { Lighting.Brightness, Lighting.ClockTime, Lighting.FogEnd, Lighting.GlobalShadows, Lighting.Ambient } end
        Lighting.Brightness, Lighting.ClockTime, Lighting.FogEnd, Lighting.GlobalShadows, Lighting.Ambient = 2, 14, 1e5, false, Color3.fromRGB(178, 178, 178)
    elseif X.bright then
        local b = X.bright X.bright = nil
        Lighting.Brightness, Lighting.ClockTime, Lighting.FogEnd, Lighting.GlobalShadows, Lighting.Ambient = b[1], b[2], b[3], b[4], b[5]
    end
    if not E.driving then
        local car = E.car()
        local C = E.controls()
        local seat = car and hum() and hum().SeatPart
        if car and seat then
            local thr = C and C:FindFirstChild("Throttle") and C.Throttle.Value or 0
            local fwd = Vector3.new(seat.CFrame.LookVector.X, 0, seat.CFrame.LookVector.Z)
            if fwd.Magnitude > 0.1 then
                fwd = fwd.Unit
                local v = seat.AssemblyLinearVelocity
                local along = v:Dot(fwd)
                local dt = math.min(X.dt or 0.016, 0.1)
                if on("cs_on") then
                    local delta
                    if thr > 0 then
                        local target = val("cs_top", 200) / 0.6
                        if along < target then delta = fwd * math.min(target - along, val("cs_accel", 90) * dt) end
                    elseif thr < 0 and along > 1 then
                        delta = -fwd * math.min(along, val("cs_brake", 180) * dt)
                    end
                    if delta then for _, p in ipairs(car:GetDescendants()) do if p:IsA("BasePart") and not p.Anchored then p.AssemblyLinearVelocity = p.AssemblyLinearVelocity + delta end end end
                end
                if on("cs_stable") and along > 60 then
                    local cf = seat.CFrame
                    local av = cf:VectorToObjectSpace(seat.AssemblyAngularVelocity)
                    seat.AssemblyAngularVelocity = cf:VectorToWorldSpace(Vector3.new(av.X * 0.85, av.Y, av.Z * 0.85))
                end
                if on("cs_upright") and seat.CFrame.UpVector.Y < 0.2 then
                    X.flipT = X.flipT or os.clock()
                    if os.clock() - X.flipT > 1.5 then local p = car:GetPivot() local _, y = p:ToEulerAnglesYXZ() car:PivotTo(CFrame.new(p.Position + Vector3.new(0, 4, 0)) * CFrame.Angles(0, y, 0)) E.zero(car) X.flipT = nil end
                else X.flipT = nil end
                X.mph = math.floor(math.abs(along) * 0.6)
            end
        end
    end
    local h = hum()
    if h and not h.SeatPart then
        if on("mv_speed") then X.baseWS = X.baseWS or h.WalkSpeed if h.WalkSpeed ~= val("mv_ws", 40) then h.WalkSpeed = val("mv_ws", 40) end
        elseif X.baseWS then h.WalkSpeed = X.baseWS X.baseWS = nil end
    end
end))
